'use client';

import { useState } from 'react';

export default function Home() {
  const [projectName, setProjectName] = useState('CreditPulse AI');
  const [toneOfVoice, setToneOfVoice] = useState('Professional, Tech-savvy, Visionary');
  const [targetAudience, setTargetAudience] = useState('Web3 VCs, Creators, Developers');
  const [inputPrompt, setInputPrompt] = useState('Smart contract automated risk-scoring system with on-chain attestations.');
  const [loading, setLoading] = useState(false);
  const [results, setResults] = useState<any>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setLoading(true);
    try {
      const res = await fetch('/api/agent', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          projectName, toneOfVoice, targetAudience, inputPrompt,
          formats: ['Pitch Deck Slides', 'X/Twitter Thread', 'Telegram Post']
        })
      });
      const data = await res.json();
      setResults(data);
    } catch (err) {
      console.error(err);
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="max-w-6xl mx-auto px-4 py-8">
      <header className="border-b border-slate-800 pb-6 mb-8 flex justify-between items-center">
        <div>
          <h1 className="text-2xl font-bold text-purple-400">MindsEcho AI</h1>
          <p className="text-xs text-slate-400">Long-Term Memory Agent for Animoca Minds Jam #1</p>
        </div>
        <span className="text-xs bg-emerald-950 text-emerald-400 border border-emerald-800 px-3 py-1 rounded-full">
          Memory Engine Active
        </span>
      </header>

      <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
        <div className="lg:col-span-5 bg-slate-900 border border-slate-800 p-6 rounded-2xl">
          <h2 className="text-lg font-semibold text-purple-300 mb-4">Agent Input</h2>
          <form onSubmit={handleSubmit} className="space-y-4">
            <div>
              <label className="block text-xs text-slate-400 mb-1">Project Name (Memory Key)</label>
              <input type="text" value={projectName} onChange={(e) => setProjectName(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded px-3 py-2 text-sm" required />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Tone of Voice</label>
              <input type="text" value={toneOfVoice} onChange={(e) => setToneOfVoice(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded px-3 py-2 text-sm" />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Target Audience</label>
              <input type="text" value={targetAudience} onChange={(e) => setTargetAudience(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded px-3 py-2 text-sm" />
            </div>
            <div>
              <label className="block text-xs text-slate-400 mb-1">Core Insight / Idea</label>
              <textarea rows={3} value={inputPrompt} onChange={(e) => setInputPrompt(e.target.value)} className="w-full bg-slate-950 border border-slate-800 rounded px-3 py-2 text-sm" required />
            </div>
            <button type="submit" disabled={loading} className="w-full bg-purple-600 hover:bg-purple-500 text-white font-medium py-2 rounded transition-all">
              {loading ? 'Processing Memory...' : 'Process & Generate Content'}
            </button>
          </form>
        </div>

        <div className="lg:col-span-7 space-y-4">
          {results ? (
            <>
              <div className="bg-purple-950/40 border border-purple-800 p-4 rounded-xl text-xs space-y-1">
                <p className="font-semibold text-purple-300">Agent Memory State Updated</p>
                <p><span className="text-slate-500">Project:</span> {results.memory?.projectName}</p>
                <p><span className="text-slate-500">Stored Insights:</span> {results.memory?.keyInsights?.length}</p>
              </div>
              {results.outputs?.map((out: any, idx: number) => (
                <div key={idx} className="bg-slate-900 border border-slate-800 p-4 rounded-xl">
                  <span className="text-xs bg-indigo-950 text-indigo-300 px-2 py-1 rounded font-semibold border border-indigo-800 inline-block mb-2">{out.platform}</span>
                  <pre className="text-xs text-slate-300 whitespace-pre-wrap font-sans bg-slate-950 p-3 rounded border border-slate-800">{out.content}</pre>
                </div>
              ))}
            </>
          ) : (
            <div className="bg-slate-900 border border-slate-800 p-12 rounded-2xl text-center text-slate-500 text-xs">
              Fill out the form on the left to start the agent memory loop.
            </div>
          )}
        </div>
      </div>
    </div>
  );
}
